#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
This module provides classes for reading analog values from an MCP3208 analog-to-digital converter (ADC)
using different SPI implementations on a Raspberry Pi.
"""

import spidev
import Adafruit_GPIO.SPI
import gpiozero
import time
import logging

__author__ = "Thomas Kaulke"
__email__ = "kaulketh@gmail.com"

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for channel range
MIN_CHANNEL = 0
MAX_CHANNEL = 7


class MCP3208Base:
    """Abstract base class for MCP3208 ADC readers."""

    def __init__(self, port: int = 0, device: int = 0):
        """Initializes the base class with common parameters."""
        self.port = port
        self.device = device

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(port={self.port}, device={self.device})"

    @property
    def info(self) -> str:
        """Returns a string containing information about the object."""
        return f"ID:{id(self)} {self.__repr__()}"

    def read(self, channel: int) -> int:
        """Abstract method for reading analog values. Must be implemented by subclasses."""
        raise NotImplementedError("Subclasses must implement the read method.")


class MCP3208Gpiozero(MCP3208Base):
    """Reads analog values using the gpiozero library."""

    def read(self, channel: int) -> int:
        """Reads the analog value from the specified channel using gpiozero."""
        if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
            raise ValueError(f"Channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}: {channel}")
        try:
            with gpiozero.MCP3208(channel=channel, differential=False, max_voltage=3.3,
                                  port=self.port, device=self.device) as adc:
                return int(adc.raw_value * 4095)  # Convert raw value to 12-bit integer
        except Exception as e:
            logger.error(f"Error reading from MCP3208 via gpiozero: {e}")
            raise


class MCP3208Adafruit(MCP3208Base):
    """Reads analog values using the Adafruit_GPIO.SPI library."""

    def __init__(self, port: int = 0, device: int = 0, speed: int = 1_000_000, mode: int = 0):
        """Initializes the Adafruit reader with SPI speed and mode."""
        super().__init__(port, device)
        self.speed = speed
        self.mode = mode
        try:
            self.spi = Adafruit_GPIO.SPI.SpiDev(self.port, self.device, max_speed_hz=self.speed, mode=self.mode)
            self.spi.set_mode(self.mode)
            self.spi.set_bit_order(Adafruit_GPIO.SPI.MSBFIRST)
        except Exception as e:
            logger.error(f"Error initializing MCP3208 via Adafruit SPI: {e}")
            raise

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(port={self.port}, device={self.device}, speed={self.speed}, mode={self.mode})"

    def read(self, channel: int) -> int:
        """Reads the analog value from the specified channel using Adafruit_GPIO."""
        if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
            raise ValueError(f"Channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}: {channel}")
        try:
            cmd = 0x80 | 0x40 | ((channel & 0x07) << 3)
            ret = self.spi.transfer([cmd, 0x0, 0x0])
            val = (ret[0] & 0x01) << 11 | ret[1] << 3 | ret[2] >> 5
            return val & 0x0FFF
        except Exception as e:
            logger.error(f"Error reading from MCP3208 via Adafruit SPI: {e}")
            raise


class MCP3208Spidev(MCP3208Base):
    """Reads analog values using the spidev library."""

    def __init__(self, port: int = 0, device: int = 0, speed: int = 1_000_000):
        """Initializes the spidev reader with SPI speed."""
        super().__init__(port, device)
        self.speed = speed
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.port, self.device)
            self.spi.max_speed_hz = self.speed
        except Exception as e:
            logger.error(f"Error initializing MCP3208 via spidev: {e}")
            raise

    def __del__(self):
        """Closes the SPI connection when the object is destroyed."""
        if self.spi:
            self.spi.close()

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(port={self.port}, device={self.device}, speed={self.speed})"

    def read(self, channel: int) -> int:
        """Reads the analog value from the specified channel using spidev."""
        if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
            raise ValueError(f"Channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}: {channel}")
        try:
            adc = self.spi.xfer2([6 | (channel & 4) >> 2, (channel & 3) << 6, 0])
            val = ((adc[1] & 15) << 8) + adc[2]
            return val
        except Exception as e:
            logger.error(f"Error reading from MCP3208 via spidev: {e}")
            raise

