# Filename: adc_demo.py

import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_BUS_NUMBER = 1
GAIN_VALUE = 1
READ_INTERVAL_SECONDS = 0.5
NUMBER_OF_CHANNELS = 4

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def create_adc_channels(adc_instance):
    """Creates AnalogIn objects for each ADC channel."""
    return [AnalogIn(adc_instance, channel) for channel in range(NUMBER_OF_CHANNELS)]

def read_adc_channels(channels):
    """Reads the raw values from a list of ADC channels."""
    return [channel.value for channel in channels]

def print_channel_values(values):
    """Prints the ADC values in a formatted table."""
    print('ADC Channel   Raw Value')
    print('------------------------')
    for channel_index, value in enumerate(values):
        print(f'Channel {channel_index}: {value}')

def main():
    """Main function to read and display ADC values."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return

    adc_channels = create_adc_channels(adc)

    try:
        while True:
            channel_values = read_adc_channels(adc_channels)
            print_channel_values(channel_values)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or ADS1115 in this library,
        # but including a finally block for potential future expansion.
        print("Program finished.")

if __name__ == "__main__":
    main()

