# heart_rate_logger_rpi.py
# Logs heart rate data from a MAX30102 sensor to a file.
# Designed for Raspberry Pi 5 in a robotics project.

import time
import board
import busio
import adafruit_max30102

# Configuration
LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1  # seconds

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the MAX30102 sensor."""
    try:
        sensor = adafruit_max30102.MAX30102(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads raw IR and RED ADC samples from the sensor."""
    try:
        ir_sample = sensor.ir
        red_sample = sensor.red
        return ir_sample, red_sample
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def estimate_bpm(peak_samples):
    """Estimates BPM from a list of peak samples."""
    if not peak_samples:
        return 0
    # Simplified BPM estimation: count peaks in a 4-second window
    return len(peak_samples)

def log_heart_rate(ir_sample, red_sample, bpm, log_file):
    """Logs heart rate data to a file."""
    timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
    try:
        with open(log_file, "a") as file:
            file.write(f"{timestamp},{ir_sample},{red_sample},{bpm}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read sensor data and log heart rate."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    peak_samples = []

    try:
        while True:
            ir_sample, red_sample = read_sensor_data(sensor)

            if ir_sample is not None and red_sample is not None:
                peak_samples.append(ir_sample)  # Use IR as proxy for heart rate peaks
                bpm = estimate_bpm(peak_samples[-4:])  # Keep a rolling 4-second window

                log_heart_rate(ir_sample, red_sample, bpm, LOG_FILE)
                print(f"Heart Rate: {bpm} BPM")

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for I2C or MAX30102 in this example
        print("Program finished.")

if __name__ == "__main__":
    main()

