import smbus2
import time
import datetime
import sqlite3
import logging
import signal
import sys
import adafruit_bmp280
import adafruit_bme280
import adafruit_ms8607

# Configure logging
logging.basicConfig(filename='error.log', level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Global variable to track program running state for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handles SIGINT (Ctrl+C) signal for graceful shutdown."""
    global running
    logging.info("Program shutting down...")
    running = False

signal.signal(signal.SIGINT, signal_handler)

def read_bmp280(bus, sensor_id):
    """Reads pressure and temperature from a BMP280 sensor."""
    try:
        bmp = adafruit_bmp280.BMP280_I2C(bus)
        pressure = bmp.pressure
        temperature = bmp.temperature
        return pressure, temperature
    except Exception as e:
        logging.error(f"Error reading BMP280 sensor {sensor_id}: {e}")
        return None, None

def read_bme280(bus, sensor_id):
    """Reads pressure, temperature, and humidity from a BME280 sensor."""
    try:
        bme = adafruit_bme280.BME280_I2C(bus)
        pressure = bme.pressure
        temperature = bme.temperature
        humidity = bme.humidity
        return pressure, temperature, humidity
    except Exception as e:
        logging.error(f"Error reading BME280 sensor {sensor_id}: {e}")
        return None, None, None

def read_ms8607(bus, sensor_id):
    """Reads pressure, temperature, and humidity from an MS8607 sensor."""
    try:
        ms8607 = adafruit_ms8607.MS8607(bus)
        pressure = ms8607.pressure
        temperature = ms8607.temperature
        humidity = ms8607.humidity
        return pressure, temperature, humidity
    except Exception as e:
        logging.error(f"Error reading MS8607 sensor {sensor_id}: {e}")
        return None, None, None

def validate_data(pressure, temperature, humidity=None):
    """Validates sensor readings against reasonable ranges."""
    if pressure is None or temperature is None:
        return False

    if not 70000 <= pressure <= 110000:
        logging.warning(f"Invalid pressure reading: {pressure} Pa")
        return False
    if not -20 <= temperature <= 50:
        logging.warning(f"Invalid temperature reading: {temperature} °C")
        return False
    if humidity is not None and not 0 <= humidity <= 100:
        logging.warning(f"Invalid humidity reading: {humidity} %")
        return False
    return True

def store_data(db_conn, timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    """Stores sensor data in the SQLite database."""
    try:
        cursor = db_conn.cursor()
        cursor.execute("""
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    """Main function to read sensor data and store it in the database."""
    try:
        # Load configuration from file
        config = {}
        try:
            with open('config.txt', 'r') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        key, value = line.split('=', 1)
                        config[key.strip()] = value.strip()
        except FileNotFoundError:
            logging.error("Config file not found. Using default values.")
        except Exception as e:
            logging.error(f"Error reading config file: {e}. Using default values.")

        # Configure I2C bus
        bus = smbus2.SMBus(1)  # Use I2C bus 1

        # Initialize sensors based on configuration
        sensors = []
        if 'Sensor1_Type' in config:
            sensor_type = config['Sensor1_Type']
            sensor_address = int(config.get('Sensor1_Address', '0x76'), 16)  # Default address
            sensor_id = config.get('Sensor1_ID', 'Sensor1')
            sampling_interval = int(config.get('Sampling_Interval_Seconds', 60))
            if sensor_type == 'BMP280':
                pressure, temperature = read_bmp280(bus, sensor_id)
                if pressure is not None and temperature is not None:
                    sensors.append((sensor_type, sensor_id, sensor_address, sampling_interval))
            elif sensor_type == 'BME280':
                pressure, temperature, humidity = read_bme280(bus, sensor_id)
                if pressure is not None and temperature is not None:
                    sensors.append((sensor_type, sensor_id, sensor_address, sampling_interval))
            elif sensor_type == 'MS8607':
                pressure, temperature, humidity = read_ms8607(bus, sensor_id)
                if pressure is not None and temperature is not None:
                    sensors.append((sensor_type, sensor_id, sensor_address, sampling_interval))
            else:
                logging.warning(f"Unknown sensor type: {sensor_type}")

        if 'Sensor2_Type' in config:
            sensor_type = config['Sensor2_Type']
            sensor_address = int(config.get('Sensor2_Address', '0x76'), 16)  # Default address
            sensor_id = config.get('Sensor2_ID', 'Sensor2')
            sampling_interval = int(config.get('Sampling_Interval_Seconds', 60))
            if sensor_type == 'BMP280':
                pressure, temperature = read_bmp280(bus, sensor_id)
                if pressure is not None and temperature is not None:
                    sensors.append((sensor_type, sensor_id, sensor_address, sampling_interval))
            elif sensor_type == 'BME280':
                pressure, temperature, humidity = read_bme280(bus, sensor_id)
                if pressure is not None and temperature is not None:
                    sensors.append((sensor_type, sensor_id, sensor_address, sampling_interval))
            elif sensor_type == 'MS8607':
