#!/usr/bin/env python3
"""
Filename: FanProportional.py
Description: Controls a 4-wire PWM fan on a Raspberry Pi based on CPU temperature
             using a functional approach with enhanced error handling and resource management.
Author: Bard
"""

import RPi.GPIO as GPIO
import time
import signal
import sys
from functools import partial

# Constants
FAN_PIN = 17
WAIT_TIME = 5
TEMPERATURE_THRESHOLDS = [65.0, 55.0, 50.0, 45.0]
PWM_VALUES = [1.0, 0.8, 0.6, 0.4]  # Corresponding PWM values for each temperature threshold
DEFAULT_PWM = 1.0  # Default PWM value (full speed)
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"

# Error handling function
def handle_error(error_message, cleanup_func=None):
    """Handles errors by printing a message and optionally running a cleanup function."""
    print(f"Error: {error_message}")
    if cleanup_func:
        try:
            cleanup_func()
        except Exception as e:
            print(f"Error during cleanup: {e}")
    sys.exit(1)

# Fan control functions
def set_fan_speed(pwm, duty_cycle):
    """Sets the fan speed by changing the PWM duty cycle."""
    try:
        pwm.ChangeDutyCycle(duty_cycle)
    except Exception as e:
        handle_error(f"Failed to set fan speed: {e}", pwm_stop) # Only need stop in case of error during speed setting

def get_cpu_temperature(temp_file):
    """Reads the CPU temperature from the specified file."""
    try:
        with open(temp_file, "r") as f:
            temp_str = f.read().strip()
            return float(temp_str) / 1000.0
    except FileNotFoundError:
        return handle_error(f"Temperature file not found: {temp_file}")
    except Exception as e:
        return handle_error(f"Failed to read CPU temperature: {e}")

def calculate_pwm(temperature, thresholds=TEMPERATURE_THRESHOLDS, pwm_values=PWM_VALUES):
    """Calculates the PWM value based on the CPU temperature and defined thresholds."""
    for i, threshold in enumerate(thresholds):
        if temperature > threshold:
            return pwm_values[i]
    return pwm_values[-1]  # Default to lowest PWM if temp is below all thresholds

# Setup/teardown functions
def gpio_setup(pin=FAN_PIN):
    """Sets up the GPIO pin for PWM output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        pwm = GPIO.PWM(pin, 100) # 100Hz PWM frequency
        pwm.start(0)
        return pwm
    except Exception as e:
        return handle_error(f"GPIO setup failed: {e}")

def gpio_cleanup(pwm=None, pin=FAN_PIN):
    """Cleans up the GPIO resources."""
    if pwm:
        pwm_stop(pwm)
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup warning: {e}") # Non-fatal error during cleanup

def pwm_stop(pwm):
    """Stops the PWM signal."""
    try:
        pwm.stop()
    except Exception as e:
        print(f"PWM stop warning: {e}") # Non-fatal error during stop

# Signal handler for graceful shutdown
def signal_handler(sig, frame, pwm, pwm_func, gpio_cleanup_func):
    """Handles signals for graceful shutdown."""
    print("You pressed Ctrl+C!")
    print("Stopping fan and cleaning up...")
    if pwm:
        pwm_func(pwm)  # Stop PWM before cleanup
    gpio_cleanup_func() # Cleanup GPIO resources
    sys.exit(0)

def main():
    """Main function to control the fan based on CPU temperature."""
    try:
        pwm = gpio_setup()
        if pwm is None:  # Handle cases where gpio_setup failed
            sys.exit(1)

        signal.signal(signal.SIGINT, partial(signal_handler, pwm=pwm, pwm_func=pwm_stop, gpio_cleanup_func=gpio_cleanup))
        signal.signal(signal.SIGTERM, partial(signal_handler, pwm=pwm, pwm_func=pwm_stop, gpio_cleanup_func=gpio_cleanup))

        print("Fan control started. Press Ctrl+C to exit.")

        while True:
            temperature = get_cpu_temperature(TEMP_FILE)
            if temperature is None: # Handle cases where temperature reading failed
                time.sleep(WAIT_TIME)
                continue

            pwm_value = calculate_pwm(temperature)
            set_fan_speed(pwm, pwm_value)
            time.sleep(WAIT_TIME)

    except Exception as e: # Catch any unexpected exceptions
        handle_error(f"An unexpected error occurred: {e}", partial(gpio_cleanup, pwm=pwm) if pwm else gpio_cleanup)

if __name__ == "__main__":
    main()

