import RPi.GPIO as GPIO
import time
import signal
import sys

# Define GPIO pins for input and output
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]

# Define a global variable to track the state of the second output pin
output_state = False

# Define a function to handle program exit gracefully
def signal_handler(sig, frame):
    print("\nExiting program...")
    GPIO.cleanup()
    sys.exit(0)

# Register the signal handler for Ctrl+C
signal.signal(signal.SIGINT, signal_handler)

# Define a function to initialize the GPIO pins
def initialize_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT)
            GPIO.output(pin, GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

# Define a function to read the input pins and control the output pins
def control_output_pins():
    global output_state
    try:
        while True:
            for i, pin in enumerate(INPUT_PINS):
                if GPIO.input(pin) == GPIO.LOW:
                    if i == 0:
                        GPIO.output(OUTPUT_PINS[0], GPIO.HIGH)
                    elif i == 1:
                        GPIO.output(OUTPUT_PINS[0], GPIO.LOW)
                    elif i == 2:
                        output_state = not output_state
                        GPIO.output(OUTPUT_PINS[1], GPIO.HIGH if output_state else GPIO.LOW)
            time.sleep(0.05)
    except Exception as e:
        print(f"Error controlling output pins: {e}")
        GPIO.cleanup()
        sys.exit(1)

# Main function
def main():
    initialize_gpio()
    control_output_pins()

if __name__ == "__main__":
    main()

