import cv2
import os
import time
import random
import string

def get_camera():
    """Initializes the camera and returns the capture object."""
    for attempt in range(3):
        try:
            cap = cv2.VideoCapture(0)
            if cap.isOpened():
                return cap
            else:
                print("Camera opened but failed to access. Retrying...")
                time.sleep(1)
        except Exception as e:
            print(f"Error initializing camera (attempt {attempt+1}): {e}")
            time.sleep(1)
    return None

def get_name():
    """Prompts the user for their name and returns it."""
    return input("Enter your name (or 'q' to quit): ").strip()

def generate_filename(name):
    """Generates a unique filename for the image."""
    return f"{name}_{random.randint(1, 1000)}.jpg"

def save_image(frame, filename):
    """Saves the image to the specified filename."""
    try:
        cv2.imwrite(filename, frame)
        print(f"Saved image: {filename}")
        return True
    except Exception as e:
        print(f"Error saving image: {e}")
        return False

def detect_faces(frame, face_cascade):
    """Detects faces in the given frame."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, 1.1, 4)

def main():
