from threading import Lock
import numpy as np
from picamera import PiCamera, PiVideoFrameType
from io import BytesIO
import cv2
import logging

logger = logging.getLogger(__name__)

class CameraStreamBuffer:
    def __init__(self, cam):
        self.cam = cam
        self.buf = BytesIO()
        self.lock = Lock()

    def write(self, d):
        with self.lock:
            if self.cam.frame.complete and self.cam.frame.frame_type != PiVideoFrameType.sps_header:
                try:
                    self.buf.write(d)
                    if self.cam._encoders.get('mjpeg', None) and self.cam._encoders['mjpeg'].done:
                        self.buf.seek(0)
                        j = self.buf.read()
                        self.buf.seek(0)
                        self.buf.truncate()
                        if j:
                            self.cam._encoders['mjpeg'].write(j)
                except Exception as e:
                    logger.error(f"Camera stream buffer error: {e}")
            else:
                self.buf.write(d)

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.buf = BytesIO()
        self.lock = Lock()
        self.prev = None
        self.cur = None

    def write(self, d):
        with self.lock:
            self.buf.write(d)
            if d.startswith(b'\xff\xd8'):
                self.buf.seek(0)
                try:
                    j = self.buf.read()
                    self.buf.seek(0)
                    self.buf.truncate()
                    if j:
                        c = cv2.imdecode(np.frombuffer(j, np.uint8), cv2.IMREAD_COLOR)
                        if c is not None:
                            self.prev = self.cur
                            self.cur = c
                            if self.prev is not None:
                                self.f(self.prev, self.cur)
                except Exception as e:
                    logger.error(f"Motion detection buffer error: {e}")

