import smbus
import time
import signal
import sys
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

# Constants for I2C bus and sensor address
I2C_BUS_NUMBER = 1
TSL2561_ADDRESS = 0x39

# Global variables for graceful shutdown
running = True
sensor = None
display_device = None
bus = None

# Signal handler for Ctrl+C
def signal_handler(sig, frame):
    """Handles Ctrl+C to ensure a clean exit."""
    global running, sensor, display_device, bus
    print("Exiting program...")
    running = False
    if sensor:
        try:
            sensor.close()
        except Exception as e:
            print(f"Error closing sensor: {e}")
    if display_device:
        try:
            display_device.clear()
        except Exception as e:
            print(f"Error clearing display: {e}")
    if bus:
        try:
            bus.close()
        except Exception as e:
            print(f"Error closing I2C bus: {e}")
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)

def initialize_i2c_bus(bus_number):
    """Initializes the I2C bus."""
    try:
        bus = smbus.SMBus(bus_number)
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_oled_display():
    """Initializes the OLED display."""
    try:
        serial_interface = i2c(port=1, address=0x3C)
        display = ssd1306(serial_interface)
        return display
    except Exception as e:
        print(f"Error initializing OLED display: {e}")
        return None

def read_tsl2561_lux(i2c_bus, address):
    """Reads the lux value from the TSL2561 sensor."""
    try:
        data0 = i2c_bus.read_i2c_block_data(address, 0x0C, 2)
        data1 = i2c_bus.read_i2c_block_data(address, 0x0E, 2)

        channel0 = data0[1] * 256 + data0[0]
        channel1 = data1[1] * 256 + data1[0]

        if channel0 == 0:
            return 0

        ratio = channel1 / float(channel0)

        if ratio >= 0 and ratio <= 0.52:
            lux = (0.0315 * channel0) - (0.05934 * channel1)
        elif ratio <= 0.65:
            lux = (0.0229 * channel0) - (0.02916 * channel1)
        elif ratio <= 0.80:
            lux = (0.0157 * channel0) - (0.0180 * channel1)
        elif ratio <= 1.3:
            lux = (0.00338 * channel0) - (0.0026 * channel1)
        else:
            lux = 0

        return max(0, lux)

    except Exception as e:
        print(f"Error reading TSL2561 sensor: {e}")
        return None

def scale_lux_to_brightness(lux_value):
    """Scales the lux value to a brightness level (0-255)."""
    return min(255, max(0, int(lux_value * 2.56)))

def display_lux_value(display, lux_value):
    """Displays the lux value on the OLED screen."""
    try:
        with canvas(display) as draw:
            draw.text((0, 0), f"Lux: {lux_value:.2f}", fill="white")
    except Exception as e:
        print(f"Error displaying lux value: {e}")

def main():
    """Main function to read sensor data and display it."""
    global bus, display_device

    bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if not bus:
        print("Failed to initialize I2C bus. Exiting.")
        sys.exit(1)

    display_device = initialize_oled_display()
    if not display_device:
        print("Failed to initialize OLED display. Exiting.")
        if bus:
            try:
                bus.close()
            except Exception as e:
                print(f"Error closing I2C bus: {e}")
        sys.exit(1)

    try:
        while running:
            lux = read_tsl2561_lux(bus, TSL2561_ADDRESS)
            if lux is not None:
                brightness_level = scale_lux_to_brightness(lux)
                display_lux_value(display_device, lux)
                print(f"Lux: {lux:.2f}, Brightness: {brightness_level}")
            time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure proper cleanup on exit
        if display_device:
            try:
                display_device.clear()
            except Exception as e:
                print(f"Error clearing display: {e}")
        if bus:
            try:
                bus.close()
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

