# Environmental monitoring script for Raspberry Pi using DHT22 and SSD1306 OLED

import time
import board
import busio
import adafruit_ssd1306
import adafruit_dht

# Define display dimensions
DISPLAY_WIDTH = 128
DISPLAY_HEIGHT = 64
DISPLAY_BORDER = 5

# Define sensor pin
DHT_PIN = board.D4

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_oled(i2c_bus):
    """Initialize the OLED display."""
    try:
        oled_display = adafruit_ssd1306.SSD1306_I2C(DISPLAY_WIDTH, DISPLAY_HEIGHT, i2c_bus)
        oled_display.fill(0)  # Clear the display
        oled_display.show()   # Update the display
        return oled_display
    except Exception as e:
        print(f"Error initializing OLED: {e}")
        return None

def initialize_dht_sensor(pin):
    """Initialize the DHT22 sensor."""
    try:
        dht_sensor = adafruit_dht.DHT22(pin)
        return dht_sensor
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}")
        return None

def read_sensor_data(dht_sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        temperature_c = dht_sensor.temperature
        humidity_percent = dht_sensor.humidity
        return temperature_c, humidity_percent
    except RuntimeError as e:
        print(f"Sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None, None

def display_data(oled_display, temperature, humidity):
    """Display temperature and humidity on the OLED screen."""
    try:
        oled_display.fill(0)  # Clear the display
        oled_display.text(f"Temp: {temperature:.1f}C", 0, 0, 1)
        oled_display.text(f"Humidity: {humidity:.1f}%", 0, 16, 1)
        oled_display.show()  # Update the display
    except Exception as e:
        print(f"Error displaying data: {e}")

def main():
    """Main function to read sensor data and display it."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    oled_display = initialize_oled(i2c_bus)
    if oled_display is None:
        return

    dht_sensor = initialize_dht_sensor(DHT_PIN)
    if dht_sensor is None:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)

            if temperature is not None and humidity is not None:
                display_data(oled_display, temperature, humidity)
                print(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
            else:
                print("Failed to retrieve data from sensor")

            time.sleep(2)

    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        # Clear the display and release resources
        oled_display.fill(0)
        oled_display.show()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

