import RPi.GPIO as GPIO
import time
import datetime

# Define the GPIO pin connected to the DHT22 data pin
DHT_PIN = 4

# Setup GPIO mode
GPIO.setmode(GPIO.BCM)

def read_dht22():
    """Reads temperature and humidity from DHT22 sensor using bit-banging."""
    try:
        # Send start signal
        GPIO.setup(DHT_PIN, GPIO.OUT)
        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.02)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        time.sleep(0.00004)

        # Setup for reading data
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        # Collect data
        data = []
        for i in range(40):
            count = 0
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                count += 1
                if count > 100:
                    return None, None
            count = 0
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                count += 1
                if count > 100:
                    return None, None
            data.append(count)

        # Process data
        bits = []
        for i in range(40):
            if data[i] > data[i-1]:
                bits.append(1)
            else:
                bits.append(0)

        # Convert bits to bytes
        bytes_ = []
        byte = 0
        for i in range(40):
            byte <<= 1
            if bits[i]:
                byte |= 1
            if (i + 1) % 8 == 0:
                bytes_.append(byte)
                byte = 0

        # Check checksum
        if bytes_[4] == (bytes_[0] + bytes_[1] + bytes_[2] + bytes_[3]) & 255:
            humidity = bytes_[0] + bytes_[1] / 10.0
            temperature = bytes_[2] + bytes_[3] / 10.0
            return temperature, humidity
        else:
            return None, None

    except Exception as e:
        print(f"Error reading DHT22: {e}")
        return None, None

def log_data(temperature, humidity):
    """Logs temperature and humidity data to a CSV file."""
    if temperature is not None and humidity is not None:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            with open("humidity_log.txt", "a") as f:
                f.write(f"{timestamp}, {temperature:.1f}, {humidity:.1f}\n")
            print(f"Logged: {timestamp}, {temperature:.1f}, {humidity:.1f}")
        except Exception as e:
            print(f"Error writing to file: {e}")

if __name__ == "__main__":
    try:
        while True:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                log_data(temperature, humidity)
            else:
                print("Failed to read DHT22 sensor.")
            time.sleep(10)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        GPIO.cleanup()

