# Script to monitor altitude using a BMP280 sensor on Raspberry Pi
import time
import board
import busio
import adafruit_bmp280

# Configuration
I2C_BUS = 1  # I2C bus number
BASELINE_READINGS = 10  # Number of readings to collect for baseline pressure
BASELINE_INTERVAL = 1  # Time between baseline readings in seconds
ALTITUDE_INTERVAL = 1  # Time between altitude readings in seconds
EXCLUDE_INITIAL_READINGS = 2  # Number of initial readings to exclude from baseline

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        return adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
    except ValueError:
        print("BMP280 sensor not found. Check I2C connection.")
        return None
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def collect_baseline_pressure(bmp280_sensor, num_readings, exclude_initial, interval):
    """Collects baseline pressure readings and calculates the average."""
    print(f"Collecting baseline pressure for {num_readings} seconds...")
    pressures = []
    for _ in range(num_readings):
        try:
            pressure = bmp280_sensor.pressure
            pressures.append(pressure)
            time.sleep(interval)
        except OSError as e:
            print(f"Error reading pressure: {e}")
            continue  # Continue to next reading
        except Exception as e:
            print(f"Unexpected error during baseline collection: {e}")
            return None  # Exit if an unexpected error occurs

    # Exclude initial readings to account for sensor settling
    valid_pressures = pressures[exclude_initial:] if exclude_initial < len(pressures) else pressures

    if not valid_pressures:
        print("No valid pressure readings collected for baseline.")
        return None

    baseline = sum(valid_pressures) / len(valid_pressures)
    print(f"Baseline pressure: {baseline:.2f} hPa")
    return baseline

def read_altitude(bmp280_sensor, baseline_pressure):
    """Reads and prints the relative altitude."""
    try:
        altitude = bmp280_sensor.altitude
        print(f"Relative altitude: {altitude:.2f} meters")
        return altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error during altitude reading: {e}")
        return None

def main():
    """Main function to run the altitude monitoring."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return  # Exit if BMP280 initialization failed

    baseline_pressure = collect_baseline_pressure(
        bmp280_sensor, BASELINE_READINGS, EXCLUDE_INITIAL_READINGS, BASELINE_INTERVAL
    )

    if baseline_pressure is None:
        return  # Exit if baseline pressure collection failed

    try:
        while True:
            read_altitude(bmp280_sensor, baseline_pressure)
            time.sleep(ALTITUDE_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

