# uart_temp_humidity_alerts_event_driven.py
# Raspberry Pi 4 Model B - Event-driven temperature/humidity monitoring with alerts

import serial
import time
import select
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
POLL_INTERVAL = 1  # seconds

# Initialize serial connection
try:
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    sys.exit(1)

# Function to read and process data
def process_data():
    """Reads data from the serial port, parses it, and triggers alerts."""
    try:
        # Use select to check if there's data available to read
        read_ready, _, _ = select.select([serial_connection], [], [], POLL_INTERVAL)

        if read_ready:
            line = serial_connection.readline().decode('ascii', errors='replace').strip()
            if line:
                try:
                    temperature, humidity = map(float, line.split(','))
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")

                    if temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                        print('Alert! Temperature or humidity exceeded threshold.')

                except ValueError:
                    print(f"Malformed data received: {line}")
        else:
            print("No data received from sensor.")

    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

# Main loop
if __name__ == "__main__":
    print("Starting temperature/humidity monitoring...")
    try:
        while True:
            process_data()
            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

