import numpy as np
import matplotlib.pyplot as plt

# Configuration constants for the thermal imaging device
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
FRAME_WIDTH = 24
FRAME_HEIGHT = 32
INTERPOLATION = 'nearest'
COLORMAP = 'inferno'
REFRESH_RATE = 0.1

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_thermal_data(serial_port):
    """Reads thermal data from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if not data:
            return None
        return [int(x) for x in data.split(',') if x.isdigit()]
    except ValueError as e:
        print(f"Error decoding data: {e}")
        return None

def process_thermal_data(data):
    """Reshapes the thermal data into a 2D array."""
    if data is None or len(data) != FRAME_WIDTH * FRAME_HEIGHT:
        return None
    return np.array(data).reshape((FRAME_HEIGHT, FRAME_HEIGHT))

def update_thermal_image(data, image, axes):
    """Updates the thermal image with new data."""
    if data is None:
        return False
    image.set_data(data)
    axes.set_title('Thermal Imaging - Raspberry Pi')
    return True

def main():
    """Main function to run the thermal imaging program."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        return

    try:
        fig, ax = plt.subplots()
        thermal_image = ax.imshow(np.zeros((FRAME_HEIGHT, FRAME_WIDTH)), interpolation=INTERPOLATION, cmap=COLORMAP)
        plt.ion()
        plt.show()

        while True:
            data = read_thermal_data(serial_connection)
            processed_data = process_thermal_data(data)

            if update_thermal_image(processed_data, thermal_image, ax):
                fig.canvas.draw_idle()
                fig.canvas.flush_events()

            time.sleep(REFRESH_RATE)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        serial_connection.close()
        plt.close(fig)

if __name__ == "__main__":
    main()

