import RPi.GPIO as GPIO
import time
import threading

class RotaryEncoder:
    """
    A class to represent a KY-040 rotary encoder connected to a Raspberry Pi.

    Attributes:
        clk_pin (int): The BCM GPIO pin connected to the CLK signal of the encoder.
        dt_pin (int): The BCM GPIO pin connected to the DT signal of the encoder.
        callback (callable, optional): A function to be called when the encoder value changes. 
                                        The function should accept a single integer argument 
                                        representing the current encoder value. Defaults to None.
        debounce_interval (float, optional): The debounce interval in seconds. Defaults to 0.005.
    """

    def __init__(self, clk_pin, dt_pin, callback=None, debounce_interval=0.005):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.debounce_interval = debounce_interval
        self.value = 0
        self.last_clk_state = None
        self.lock = threading.Lock()  # Lock for thread safety
        self._setup_gpio()

    def _setup_gpio(self):
        """Sets up the GPIO pins for the rotary encoder."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

            self.last_clk_state = GPIO.input(self.clk_pin)

            GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self._rotation_detected, bouncetime=int(self.debounce_interval * 1000))
            GPIO.add_event_detect(self.dt_pin, GPIO.BOTH, callback=self._rotation_detected, bouncetime=int(self.debounce_interval * 1000))

        except Exception as e:
            raise RuntimeError(f"GPIO setup failed: {e}")


    def _rotation_detected(self, channel):
        """Handles rotation detection and updates the encoder value."""

        try:
            with self.lock:  # Acquire lock for thread safety
                clk_state = GPIO.input(self.clk_pin)
                dt_state = GPIO.input(self.dt_pin)

                if clk_state != self.last_clk_state:
                    if dt_state != clk_state:
                        self.value += 1
                    else:
                        self.value -= 1

                    self.last_clk_state = clk_state

                    if self.callback:
                        try:
                            self.callback(self.value)  # Invoke callback in separate thread
                        except Exception as callback_error:
                            print(f"Callback error: {callback_error}")

        except Exception as e:
            print(f"Error during rotation detection: {e}")



    def cleanup(self):
        """Cleans up the GPIO pins."""
        try:
            GPIO.remove_event_detect(self.clk_pin)
            GPIO.remove_event_detect(self.dt_pin)
            GPIO.cleanup()
        except Exception as e:
            print(f"GPIO cleanup failed: {e}")


if __name__ == '__main__':

    def my_callback(value):
        """Example callback function."""
        print(f"Encoder value: {value}")


    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=my_callback)
        print("Rotary encoder example. Press Ctrl+C to exit.")
        while True:
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("Exiting program...")
        encoder.cleanup()

    except Exception as e:
        print(f"An error occurred: {e}")
        GPIO.cleanup()

