# Predictive maintenance for urban monitoring using vibration sensor
# Subcategory marker: vibration
import RPi.GPIO as GPIO
import time
import random

# GPIO pin for the vibration sensor (BCM numbering)
VIBRATION_SENSOR_PIN = 17

# Configure the GPIO pin with a pull-up resistor for the active-low sensor
def setup_gpio():
    """Set up the GPIO pin with a pull-up resistor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(VIBRATION_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

# Read the vibration sensor and simulate amplitude for predictive maintenance
def read_vibration_sensor():
    """Read the vibration sensor and return a simulated amplitude."""
    # The sensor is active-low, so LOW means vibration detected
    if GPIO.input(VIBRATION_SENSOR_PIN) == GPIO.LOW:
        return random.uniform(6.0, 9.0)
    return random.uniform(3.0, 5.0)

# Track vibration trends over a short window for predictive maintenance
def track_vibration_trends(num_samples=6):
    """Collect vibration samples and return the running average amplitude."""
    amplitudes = []
    for _ in range(num_samples):
        amplitudes.append(read_vibration_sensor())
        time.sleep(0.3)
    return sum(amplitudes) / len(amplitudes)

# Main entry point for the predictive maintenance script
if __name__ == "__main__":
    try:
        setup_gpio()
        average_amplitude = track_vibration_trends()
        # Compare the average amplitude to a threshold for maintenance advice
        if average_amplitude > 7.5:
            print("Maintenance recommended: wear trend is high")
        else:
            print("Component healthy: no action needed")
    except Exception as error:
        # Report any setup or read errors without crashing
        print("Predictive maintenance error:", error)
    finally:
        # Always release the GPIO resources
        GPIO.cleanup()

