import random
import time
from gpiozero import LED

# Define the GPIO pin for the LED
LED_PIN = 23

# Define the moisture threshold
MOISTURE_THRESHOLD = 30

# Function to simulate reading soil moisture
def read_soil_moisture():
    """Simulates reading soil moisture and returns a percentage."""
    return random.randint(0, 100)

# Context manager for the LED
class LEDController:
    def __init__(self, pin):
        self.led = LED(pin)

    def __enter__(self):
        return self.led

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.led.off()
        self.led.close()

# Main function to run the watering system simulation
def run_watering_system():
    """Simulates a plant watering system based on soil moisture."""
    try:
        with LEDController(LED_PIN) as led:
            for _ in range(3):
                moisture_level = read_soil_moisture()
                print(f"Soil Moisture: {moisture_level}%")

                if moisture_level < MOISTURE_THRESHOLD:
                    print("Watering complete.")
                    led.on()
                    time.sleep(2)
                    led.off()
                else:
                    print("Moisture sufficient.")

                time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram interrupted. Shutting down...")
    finally:
        print("System shutdown complete.")

# Run the simulation
if __name__ == "__main__":
    run_watering_system()

