#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
AMSpi class - Python class for controlling Arduino Motor Shield L293D from Raspberry Pi.

License: MIT
Author: Jan Lipovský <janlipovsky@gmail.com>, janlipovsky.cz
Contributors: Daniel Neumann, Bard
"""

import logging
import threading
import RPi.GPIO as GPIO
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Motor identification constants
MOTOR_1 = 1
MOTOR_2 = 2

# Define motor directions
CLOCKWISE = "clockwise"
COUNTER_CLOCKWISE = "counter_clockwise"
STOP = "stop"

# Define default PWM frequency
DEFAULT_PWM_FREQUENCY = 100  # Hz

def _setup_gpio(pin, mode):
    """Sets up a GPIO pin."""
    try:
        GPIO.setup(pin, mode)
        return True
    except Exception as e:
        logging.error(f"GPIO setup error on pin {pin}: {e}")
        return False

def _pwm_setup(pin, frequency):
    """Sets up a PWM instance."""
    try:
        pwm = GPIO.PWM(pin, frequency)
        pwm.start(0)  # Start PWM with 0 duty cycle
        return pwm
    except Exception as e:
        logging.error(f"PWM setup error on pin {pin}: {e}")
        return None


class Motor:
    """Represents a single DC motor."""

    def __init__(self, motor_id, pins, direction_bits, shift_register, pwm_frequency=DEFAULT_PWM_FREQUENCY):
        self.motor_id = motor_id
        self.pins = pins  # GPIO pins for the motor (enable, input1, input2)
        self.direction_bits = direction_bits # Bits for controlling the motor direction in the shift register
        self.shift_register = shift_register
        self.pwm_frequency = pwm_frequency
        self.pwm = None # PWM instance for the motor's enable pin
        self._setup()

    def _setup(self):
        """Initializes the motor's GPIO pins and PWM."""
        if not _setup_gpio(self.pins[0], GPIO.OUT): return False # Enable pin
        if not _setup_gpio(self.pins[1], GPIO.OUT): return False # Input 1 pin
        if not _setup_gpio(self.pins[2], GPIO.OUT): return False # Input 2 pin

        self.pwm = _pwm_setup(self.pins[0], self.pwm_frequency)
        if not self.pwm: return False

        self.stop() # Ensure motor is initially stopped
        return True

    def _set_direction(self, direction):
        """Sets the motor's direction by writing to the shift register."""
        if direction not in [CLOCKWISE, COUNTER_CLOCKWISE, STOP]:
            raise ValueError("Invalid direction. Must be 'clockwise', 'counter_clockwise', or 'stop'.")
        try:
            self.shift_register.write(self.direction_bits[self.motor_id - 1][direction])
        except Exception as e:
            logging.error(f"Error writing to shift register for motor {self.motor_id}: {e}")

    def clockwise(self, duty_cycle=100):
        """Sets the motor to clockwise rotation."""
        self._set_direction(CLOCKWISE)
        self.change_duty_cycle(duty_cycle)

    def counter_clockwise(self, duty_cycle=100):
        """Sets the motor to counter-clockwise rotation."""
        self._set_direction(COUNTER_CLOCKWISE)
        self.change_duty_cycle(duty_cycle)

    def stop(self):
        """Stops the motor."""
        self._set_direction(STOP)
        if self.pwm:
            self.pwm.ChangeDutyCycle(0)

    def change_duty_cycle(self, duty_cycle):
        """Changes the motor's speed."""
        if not 0 <= duty_cycle <= 100:
            raise ValueError("Duty cycle must be between 0 and 100.")
        if self.pwm:
            self.pwm.ChangeDutyCycle(duty_cycle)

    def stop_all_motors(self):
        """Stops the motor and releases resources."""
        self.stop()
        if self.pwm:
            self.pwm.stop()



class ShiftRegister:
    """Manages the 74HC595 shift register."""

    def __init__(self, data_pin, clock_pin, latch_pin):
        self.data_pin = data_pin
        self.clock_pin = clock_pin
        self.latch_pin = latch_pin
        if not _setup_gpio(self.data_pin, GPIO.OUT): return False
        if not _setup_gpio(self.clock_pin, GPIO.OUT): return False
        if not _setup_gpio(self.latch_pin, GPIO.OUT): return False
        self._setup()

    def _setup(self):
        """Initializes the shift register pins."""
        pass # Already setup in __init__

    def write(self, value):
        """Writes a byte to the shift register."""
        try:
            for i in range(8):
                GPIO.output(self.clock_pin, GPIO.LOW)
                GPIO.output(self.data_pin, GPIO.HIGH if (value >> (7 - i)) & 1 else GPIO.LOW)
                GPIO.output(self.clock_pin, GPIO.HIGH)
            GPIO.output(self.latch_pin, GPIO.HIGH)
            GPIO.output(self.latch_pin, GPIO.LOW)
        except Exception as e:
            logging.error(f"Error writing to shift register: {e}")


class MotorShield:
    """Main class for controlling the Arduino Motor Shield."""

    def __init__(self, l293d_pin, pwm_frequency=DEFAULT_PWM_FREQUENCY):
        self.l293d_pin = l293d_pin
        self.pwm_frequency = pwm_frequency
        self.motors = {}
        self.shift_register = None
        self._setup_gpio()
        if not _setup_gpio(self.l293d_pin, GPIO.OUT): return False
        self._setup()

    def _setup_gpio(self):
        """Sets up the Raspberry Pi GPIO."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
        except Exception as e:
            logging.error(f"GPIO setup error: {e}")
            raise

    def _setup(self):
        """Initializes the motor shield and shift register."""
        if not self.shift_register:
            self.shift_register = ShiftRegister(data_pin=10, clock_pin=9, latch_pin=11)
            # Define direction bits for motors 1 and 2.  These control the shift register.
            self.motors[MOTOR_1] = Motor(MOTOR_1, pins=(13, 3, 4), direction_bits={
                CLOCKWISE: 0b00000010, STOP: 0b00000000, COUNTER_CLOCKWISE: 0b00000001
            }, shift_register=self.shift_register, pwm_frequency=self.pwm_frequency)
            self.motors[MOTOR_2] = Motor(MOTOR_2, pins=(12, 5, 6), direction_bits={
                CLOCKWISE: 0b00001000, STOP: 0b00000000, COUNTER_CLOCKWISE: 0b00000100
            }, shift_register=self.shift_register, pwm_frequency=self.pwm_frequency)


    def get_motor(self, motor_id):
        """Returns a Motor object by ID."""
        return self.motors.get(motor_id)

    def stop_all_motors(self):
        """Stops all motors and cleans up GPIO."""
        for motor in self.motors.values():
            motor.stop_all_motors()
        GPIO.cleanup()


def example_usage():
    """Demonstrates how to use the MotorShield class."""

    def control_motors(shield):
        """Example function to control the motors."""
        motor1 = shield.get_motor(MOTOR_1)
        motor2 = shield.get_motor(MOTOR_2)

        if not motor1 or not motor2:
            logging.error("Motors not initialized.")
            return

        try:
            motor1.clockwise(duty_cycle=75)
            motor2.counter_clockwise(duty_cycle=50)
            logging.info("Motors started.")
            # ... (rest of the example logic)
        except Exception as e:
            logging.error(f"Error during motor control: {e}")
        finally:
            motor1.stop_all_motors()
            motor2.stop_all_motors()


    try:
        shield = MotorShield(l293d_pin=25) # Example l293d_pin
        control_motors(shield)
    except Exception as e:
        logging.error(f"Initialization error: {e}")
    finally:
        GPIO.cleanup() # Ensure cleanup even if errors occur during initialization


if __name__ == "__main__":
    example_usage()

