class AimingController:
    def __init__(self, ld, hd):
        self.pz = 128
        self.ph = 128
        self.vy = [75,75,75,72,72,72,68,68,68,90]
        self.hx = [133,128,122,133,128,122,133,128,122,128]
        self.ld = ld
        self.hd = hd
        self.laser = 0

    def aim_blocks(self, nums):
        try:
            with open("/dev/servoblaster", "w+") as f:
                for i in sorted(range(len(nums)), key=lambda k: nums[k]):
                    sleep(self.ld/2)
                    f.write(f"0={self.hx[i]}\n")
                    f.write(f"1={self.vy[i]}\n")
                    sleep(self.ld/2)
                    print(f"Aiming at block {i+1}/{len(nums)}")
                    self.laser_on()
                    sleep(self.hd)
                    self.laser_off()
                    self.ph = self.hx[i]
                    self.pz = self.vy[i]
        except Exception as e:
            print(f"Error: {e}")
        finally:
            self.laser_off()

    def calibrate(self, h, v):
        try:
            with open("/dev/servoblaster", "w+") as f:
                f.write(f"0={h}\n")
                f.write(f"1={v}\n")
                self.ph = h
                self.pz = v
        except Exception as e:
            print(f"Error: {e}")

