# Raspberry Pi radiation monitoring system using UART and event-driven approach.

import serial
import time
import RPi.GPIO as GPIO
import select
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_GPIO_PIN = 18
ALARM_THRESHOLD = 50.0
READ_INTERVAL = 1

# Global variables
serial_connection = None
alarm_state = False

def initialize_serial(port, baud, timeout):
    """Initializes the serial connection."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Initially off

def read_radiation_level(serial_port):
    """Reads a line from the serial port and returns the radiation level."""
    try:
        if serial_port.in_waiting > 0:
            line = serial_port.readline().decode('ascii', errors='replace').strip()
            if line:
                try:
                    return float(line)
                except ValueError:
                    print(f"Invalid data received: {line}")
                    return None
            else:
                return None
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def update_alarm_state(gpio_pin, level, threshold):
    """Updates the alarm state based on the radiation level."""
    global alarm_state
    if level is not None:
        if level > threshold and not alarm_state:
            GPIO.output(gpio_pin, GPIO.HIGH)
            print("ALARM: Radiation level exceeded threshold!")
            alarm_state = True
        elif level <= threshold and alarm_state:
            GPIO.output(gpio_pin, GPIO.LOW)
            print("Alarm cleared.")
            alarm_state = False

def main_loop(serial_port, gpio_pin, threshold, read_interval):
    """Main loop to read data, update alarm, and handle events."""
    while True:
        radiation_level = read_radiation_level(serial_port)
        if radiation_level is not None:
            print(f"Radiation Level: {radiation_level:.2f} µSv/h")
            update_alarm_state(gpio_pin, radiation_level, threshold)
        time.sleep(read_interval)

def cleanup(serial_port, gpio_pin):
    """Cleans up resources before exiting."""
    print("Cleaning up resources...")
    if serial_port:
        serial_port.close()
    GPIO.cleanup()
    print("Cleanup complete.")

if __name__ == "__main__":
    try:
        serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
        initialize_gpio(ALARM_GPIO_PIN)
        main_loop(serial_connection, ALARM_GPIO_PIN, ALARM_THRESHOLD, READ_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        cleanup(serial_connection, ALARM_GPIO_PIN)

