# Raspberry Pi script to read GPS data and extract latitude/longitude.

import serial
import time
import pynmea2

SERIAL_PORT = "/dev/serial0"  # GPS module serial port
BAUD_RATE = 9600  # Baud rate for serial communication
READ_TIMEOUT = 1  # Timeout for reading data from the serial port (seconds)


def configure_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        ser = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def parse_gps_data(serial_port):
    """Reads data from the serial port and parses it for GPS coordinates."""
    try:
        while True:
            try:
                line = serial_port.readline().decode('ascii', errors='replace')
                if line.startswith('$GPRMC'):
                    msg = pynmea2.parse(line)
                    if msg.is_data_valid():
                        latitude = msg.latitude
                        longitude = msg.longitude
                        print(f"Latitude: {latitude}, Longitude: {longitude}")
            except pynmea2.ParseError as e:
                print(f"Error parsing NMEA sentence: {e}")
            except UnicodeDecodeError as e:
                print(f"Unicode decode error: {e}")

            time.sleep(1)  # Wait for 1 second before reading again

    except KeyboardInterrupt:
        print("Script interrupted by user. Exiting...")
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")


def main():
    """Main function to initialize and run the GPS data parser."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)

    if serial_connection:
        parse_gps_data(serial_connection)
    else:
        print("Failed to initialize serial port. Exiting.")


if __name__ == "__main__":
    main()

