import serial
import time
import os

# Define GPS module settings
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Define log file name
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return None


def parse_gpgga_data(data):
    """Parses GPGGA sentence to extract latitude, longitude, and altitude."""
    try:
        if data.startswith('$GPGGA'):
            parts = data.split(',')
            if parts[6] == '1':  # Check for fix quality: 0=invalid, 1=GPS fix
                latitude = parts[2]
                longitude = parts[4]
                altitude = parts[9]
                return latitude, longitude, altitude
    except Exception as e:
        print(f"Error parsing GPGGA data: {e}")
    return None, None, None


def log_coordinates(log_file, timestamp, latitude, longitude, altitude):
    """Logs the GPS coordinates to a file."""
    try:
        with open(log_file, 'a') as file:
            file.write(f"{timestamp}, {latitude}, {longitude}, {altitude}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def main():
    """Main function to read GPS data and log coordinates."""
    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        return

    try:
        while True:
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                latitude, longitude, altitude = parse_gpgga_data(line)

                if latitude and longitude and altitude:
                    timestamp = time.strftime('%Y-%m-%dT%H:%M:%SZ')
                    log_coordinates(LOG_FILE, timestamp, latitude, longitude, altitude)
                    print(f"Coordinates logged - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}")

                time.sleep(1)

            except Exception as e:
                print(f"Error in main loop: {e}")
                time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

