# Log file path
LOG_FILE = 'water_flow_log.txt'

# Global variable to store the serial port
serial_port = None

def read_flow_rate():
    """Reads flow rate from the serial port and logs it."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if data:
            try:
                flow_rate = float(data)
                print(f'Flow Rate: {flow_rate} L/min')
                log_data(f'Flow Rate: {flow_rate} L/min')
            except ValueError:
                print(f"Warning: Invalid data received: {data}")
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def log_data(data):
    """Logs the given data to the log file with a timestamp."""
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(f'{time.strftime('%Y-%m-%d %H:%M:%S')} - {data}\n')
    except IOError as e:
        print(f"Error writing to log file: {e}")

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    print("\nExiting program...")
    if serial_port:
        serial_port.close()
        print("Serial port closed.")
