#!/usr/bin/env python3
"""
Raspberry Pi Web API for UART Instrument Control and Data Management.

This script provides a robust and performant web API using Flask, serving
real-world data from a USB-serial instrument (e.g., a bench power supply)
and managing a small in-memory database of todo items. It emphasizes
idempotency, immutability, and functional programming principles.
"""

import json
import time
import logging
import threading
import signal
import os
from datetime import datetime

from flask import Flask, Response, request, jsonify, abort
import serial

# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Application Constants
UART_PORT = os.environ.get("UART_PORT", "/dev/ttyUSB0")
UART_BAUDRATE = int(os.environ.get("UART_BAUDRATE", 9600))
UART_TIMEOUT = float(os.environ.get("UART_TIMEOUT", 1))
WEB_SERVER_HOST = os.environ.get("WEB_SERVER_HOST", "0.0.0.0")
WEB_SERVER_PORT = int(os.environ.get("WEB_SERVER_PORT", 5000))
TODO_DATA_FILE = os.environ.get("TODO_DATA_FILE", "todo.json")

# Global Variables
app = Flask(__name__)
todo_data = []
next_id = 1
uart_port = None  # Global UART port object
data_lock = threading.Lock()  # Lock for thread-safe access to todo_data
shutdown_flag = False  # Flag to signal shutdown

# --- UART Communication Functions ---
def open_uart_port(port, baudrate, timeout):
    """Opens the UART port with retry logic."""
    retries = 3
    for i in range(retries):
        try:
            ser = serial.Serial(port, baudrate, timeout=timeout)
            logging.info(f"UART port {port} opened successfully.")
            return ser
        except serial.SerialException as e:
            logging.error(f"Failed to open UART port {port}: {e}")
            if i < retries - 1:
                time.sleep(2 ** i)  # Exponential backoff
            else:
                logging.error("Max UART port open retries reached.")
                return None
    return None

def close_uart_port(port):
    """Closes the UART port if it's open."""
    if port and port.is_open:
        port.close()
        logging.info("UART port closed.")

def send_uart_command(port, command):
    """Sends a command to the UART port."""
    try:
        port.write(command.encode('ascii'))
        logging.debug(f"Sent command: {command}")
    except serial.SerialException as e:
        logging.error(f"Failed to send command: {e}")
        return None
    return True

def read_uart_response(port, timeout=1):
    """Reads the response from the UART port."""
    try:
        response = port.readline().decode('ascii', errors='replace').strip()
        logging.debug(f"Received response: {response}")
        return response
    except serial.SerialException as e:
        logging.error(f"Failed to read response: {e}")
        return None

def get_instrument_idn(port):
    """Retrieves the instrument's identification string."""
    if not port:
        logging.error("UART port not initialized.")
        return None
    if send_uart_command(port, "*IDN?\n"):
        response = read_uart_response(port)
        return response
    return None

# --- Data Management Functions ---
def load_todo_data(filename=TODO_DATA_FILE):
    """Loads todo data from a JSON file."""
    global next_id
    try:
        with open(filename, 'r') as f:
            data = json.load(f)
            next_id = max(item['id'] for item in data) + 1 if data else 1
            return data
    except FileNotFoundError:
        logging.warning(f"File not found: {filename}. Creating a new file.")
        return []
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON in {filename}. Returning empty data.")
        return []
    except Exception as e:
        logging.error(f"Error loading data: {e}")
        return []

def save_todo_data(data, filename=TODO_DATA_FILE):
    """Saves todo data to a JSON file."""
    try:
        with open(filename, 'w') as f:
            json.dump(data, f, indent=2)
        logging.info(f"Data saved to {filename}")
    except Exception as e:
        logging.error(f"Error saving data: {e}")

def get_all_items():
    """Returns all todo items."""
    with data_lock:
        return todo_data

def get_item_by_id(item_id):
    """Returns a todo item by ID."""
    with data_lock:
        for item in todo_data:
            if item['id'] == item_id:
                return item
        return None

def create_new_item(name, done=False):
    """Creates a new todo item."""
    global next_id
    timestamp = datetime.utcnow().isoformat() + 'Z'
    item = {
        'id': next_id,
        'name': name,
        'done': bool(done),
        'created': timestamp,
        'updated': timestamp
    }
    with data_lock:
        todo_data.append(item)
        next_id += 1
    save_todo_data(todo_data)
    return item

# --- Web API Endpoints ---
@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Retrieves the instrument's version information."""
    global uart_port
    if not uart_port:
        return Response("Instrument not initialized.\n", mimetype='text/plain', status=500)

    version = get_instrument_idn(uart_port)
    if version:
        return Response(version + "\n", mimetype='text/plain')
    else:
        return Response("Failed to retrieve version.\n", mimetype='text/plain', status=504)

@app.route('/data', methods=['GET'])
def handle_get_data():
    """Handles GET requests to /data."""
    if request.args.get('id'):
        item_id = int(request.args.get('id'))
        item = get_item_by_id(item_id)
        if item:
            return jsonify(item)
        else:
            return Response("Item not found\n", mimetype='text/plain', status=404)
    else:
        return jsonify(get_all_items())

@app.route('/data', methods=['POST'])
def handle_post_data():
    """Handles POST requests to /data."""
    try:
        data = request.get_json()
        if not data or 'name' not in data:
            return Response("Invalid request: 'name' is required\n", mimetype='text/plain', status=400)

        item = create_new_item(data['name'], data.get('done', False))
        return jsonify(item), 201
    except Exception as e:
        logging.error(f"Error handling POST request: {e}")
        return Response("Internal server error\n", mimetype='text/plain', status=502)

@app.route('/shutdown', methods=['POST'])
def shutdown_server():
    """Initiates a graceful shutdown of the web server."""
    global shutdown_flag
    shutdown_flag = True
    return Response("Shutting down...\n", mimetype='text/plain', status=200)

# --- Signal Handler ---
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info(f"Received signal {sig}. Shutting down...")
    global shutdown_flag
    shutdown_flag = True

# --- Main Function ---
def main():
    """Main function to initialize and run the application."""
    global uart_port

    # Load data
    global todo_data
    todo_data = load_todo_data()

    # Initialize UART port
    uart_port = open_uart_port(UART_PORT, UART_BAUDRATE, UART_TIMEOUT)
    if not uart_port:
        logging.error("Failed to initialize UART port. Exiting.")
        return 1

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start the web server
    try:
        app.run(host=WEB_SERVER_HOST, port=WEB_SERVER_PORT, debug=False, use_reloader=False)
    except Exception as e:
        logging.error(f"Web server error: {e}")
        return 1
    finally:
        # Ensure resources are released
        close_uart_port(uart_port)
        logging.info("Application shutdown complete.")

if __name__ == '__main__':
    main()

