import serial
import time
import datetime

# Configuration for the RFID reader
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1  # seconds

# Log file path
LOG_FILE = 'access_log.txt'

def initialize_serial(port, baud, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_rfid_tag(serial_connection):
    """Reads an RFID tag from the serial port."""
    try:
        tag = serial_connection.readline().decode('ascii', errors='replace').strip()
        return tag
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def log_access_event(tag_id, log_filepath):
    """Logs the access event to a file."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f"{timestamp} - RFID Tag: {tag_id}\n"
    try:
        with open(log_filepath, 'a') as log_file:
            log_file.write(log_entry)
        print(f"Access granted for RFID Tag: {tag_id}")
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to continuously monitor the RFID reader."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            tag_id = read_rfid_tag(serial_connection)
            if tag_id:
                log_access_event(tag_id, LOG_FILE)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

