# energy_meter_uart_rpi.py
# Reads power consumption data from a smart energy meter via UART on Raspberry Pi
# Logs the data to a file with a timestamp.

import serial
import time
import os
import contextlib

# Configuration
SERIAL_PORT = '/dev/serial0'  # UART port on Raspberry Pi
BAUD_RATE = 9600
TIMEOUT = 1  # seconds
LOG_FILE = 'power_consumption.log'

def open_serial_port(port, baudrate, timeout):
    """Opens and returns a serial port."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_meter_data(serial_port):
    """Reads a line of data from the serial port."""
    try:
        return serial_port.readline().decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def parse_power_value(data):
    """Parses the power value from the data string."""
    try:
        return float(data)
    except ValueError:
        print(f"Invalid data received: {data}")
        return None

def log_power_consumption(power_value, log_file):
    """Logs the power consumption to a file with a timestamp."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(log_file, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log power consumption data."""
    with contextlib.closing(open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)) as serial_port:
        if serial_port is None:
            return

        try:
            while True:
                data = read_meter_data(serial_port)
                if data:
                    power_value = parse_power_value(data)
                    if power_value is not None:
                        log_power_consumption(power_value, LOG_FILE)
        except KeyboardInterrupt:
            print("Exiting program.")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

