def log_power_consumption(power_value, log_file):
    """Logs the power consumption to a file with a timestamp."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(log_file, 'a') as logfile:
            logfile.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log power consumption data."""
    with contextlib.closing(open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)) as serial_port:
        if serial_port is None:
            return

        try:
            while True:
                data = read_meter_data(serial_port)
                if data:
                    power_value = parse_power_value(data)
                    if power_value is not None:
                        log_power_consumption(power_value, LOG_FILE)
        except KeyboardInterrupt:
            print("Exiting program.")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

