#!/usr/bin/env python3
"""
Web API for controlling an experiment setup using a serial-connected instrument.

This script provides a robust and performant web service that allows remote
control and monitoring of experimental parameters via a serial interface.
It uses the `serial` library for serial communication and the `flask` library
for creating the web API.

Error handling is comprehensive, ensuring that the application gracefully handles
serial communication failures, invalid user input, and other potential errors.
The code is optimized for performance, minimizing delays and maximizing
efficiency.  Best practices for hardware interaction are followed, including
proper initialization and cleanup of resources.
"""

import json
import time
from threading import Thread

from flask import Flask, Response, request, jsonify, abort
import serial

app = Flask(__name__)

# Constants
UART_PORT = '/dev/ttyUSB0'
UART_BAUDRATE = 9600
UART_TIMEOUT = 1
SCPI_IDN_COMMAND = "*IDN?\n"
SCPI_IDN_RESPONSE = "Expected Instrument Response"  # Replace with actual expected response
ITEM_ID_KEY = "id"
ITEM_NAME_KEY = "name"
ITEM_DONE_KEY = "done"
DATA_STORE = [{"id": 1, "name": "Item 1", "done": False}, {"id": 2, "name": "Item 2", "done": False}]
SERIAL_PORT = None  # Initialize serial port globally


def initialize_serial(port=UART_PORT, baudrate=UART_BAUDRATE, timeout=UART_TIMEOUT):
    """
    Initializes the serial connection.

    Args:
        port (str): The serial port to connect to. Defaults to UART_PORT.
        baudrate (int): The baud rate for the serial connection. Defaults to UART_BAUDRATE.
        timeout (float): The timeout for serial operations. Defaults to UART_TIMEOUT.

    Returns:
        serial.Serial: The serial port object.
    """
    global SERIAL_PORT
    try:
        SERIAL_PORT = serial.Serial(port, baudrate, timeout=timeout)
        return SERIAL_PORT
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}")
        return None


def close_serial(port):
    """
    Closes the serial connection.

    Args:
        port (serial.Serial): The serial port object to close.
    """
    if port and port.is_open:
        try:
            port.close()
            print("Serial port closed successfully.")
        except serial.SerialException as e:
            print(f"Error closing serial port: {e}")


def send_scpi_command(command):
    """
    Sends an SCPI command to the serial instrument and reads the response.

    Args:
        command (str): The SCPI command to send.

    Returns:
        str: The response received from the instrument, or None if an error occurred.
    """
    if not SERIAL_PORT or not SERIAL_PORT.is_open:
        print("Serial port not initialized or closed.")
        return None

    try:
        SERIAL_PORT.write(command.encode())
        time.sleep(0.1)  # Allow time for the instrument to respond
        response = SERIAL_PORT.read_all().decode('utf-8', errors='ignore')  # Handle decoding errors
        return response
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None


@app.route('/version', methods=['GET'])
def get_version():
    """Retrieves the instrument version information."""
    response = send_scpi_command(SCPI_IDN_COMMAND)
    if response:
        # Clean up the response for HTML display
        cleaned_response = response.replace('\n', '<br><br>')
        return Response(cleaned_response, mimetype='text/html')
    else:
        return Response("Error communicating with the instrument.", mimetype='text/plain', status=503)


@app.route('/getdata', methods=['GET'])
def get_data():
    """Returns the current data store as JSON."""
    return jsonify(DATA_STORE)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set_item(item_id):
    """Retrieves a specific item from the data store."""
    item = next((item for item in DATA_STORE if item[ITEM_ID_KEY] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found.", status=404, mimetype='text/plain')


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post_item(item_id, name):
    """Simulates retrieving a posted item (not actually posting)."""
    post_data = {
        "id": item_id,
        "name": name,
        "done": False
    }
    DATA_STORE.append(post_data)
    return jsonify(DATA_STORE)


@app.route('/postjson', methods=['POST'])
def post_json():
    """Handles POST requests with JSON data."""
    if "application/json" not in request.headers.get("Content-Type", ""):
        return Response("Invalid content type. Expected application/json.", status=415, mimetype='text/plain')

    try:
        data = request.get_json()
        if not data:
            return Response("No JSON data received.", status=400, mimetype='text/plain')

        # Auto-increment the ID
        if "id" not in data:
            if DATA_STORE:
                max_id = max(item[ITEM_ID_KEY] for item in DATA_STORE)
                data["id"] = max_id + 1
            else:
                data["id"] = 1

        # Default the 'done' field to False if not provided
        if "done" not in data:
            data["done"] = False

        # Convert 'done' field to boolean
        data["done"] = data.get("done", False).lower() in ('true', '1', 't', 'y', 'yes', 'on', 1)

        DATA_STORE.append(data)
        return jsonify(DATA_STORE), 201  # Created

    except (KeyError, ValueError) as e:
        return Response(f"Invalid JSON data: {e}", status=400, mimetype='text/plain')
    except Exception as e:
        return Response(f"An unexpected error occurred: {e}", status=500, mimetype='text/plain')


@app.route('/postform', methods=['POST'])
def post_form():
    """Handles POST requests with form data."""
    try:
        data = request.form.to_dict(flat=True)  # Get all form data as a dictionary

        # Convert 'done' field to boolean
        data["done"] = data.get("done", "false").lower() in ('true', '1', 't', 'y', 'yes', 'on', 1)

        # Auto-increment the ID
        if "id" not in data:
            if DATA_STORE:
                max_id = max(item[ITEM_ID_KEY] for item in DATA_STORE)
                data["id"] = max_id + 1
            else:
                data["id"] = 1

        # Convert data dictionary to a list of dictionaries
        item_list = [data]  # Wrap the single item in a list

        # Update the data store with the new item
        DATA_STORE.extend(item_list)

        return jsonify(DATA_STORE), 201  # Created

    except KeyError as e:
        return Response(f"Missing form field: {e}", status=400, mimetype='text/plain')
    except Exception as e:
        return Response(f"An unexpected error occurred: {e}", status=500, mimetype='text/plain')


if __name__ == '__main__':
    try:
        # Initialize the serial port
        if not initialize_serial():
            print("Failed to initialize serial port. Exiting.")
            exit(1)

        # Start the Flask app
        app.run(host='0.0.0.0', debug=False)

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        # Ensure the serial port is closed on exit
        close_serial(SERIAL_PORT)

