import serial
import time
import select
import sys

# Define Bluetooth serial port and baud rate
bluetooth_port = "/dev/rfcomm4"
bluetooth_baudrate = 38400

# Function to send command via Bluetooth
def send_bluetooth_command(command):
    """Sends a command over Bluetooth."""
    try:
        with serial.Serial(bluetooth_port, bluetooth_baudrate) as ser:
            ser.write(f"X{command}\n".encode())
    except serial.SerialException as e:
        raise RuntimeError(f"Bluetooth communication error: {e}")

def main():
    """Main function to handle user input and send commands."""
    try:
        while True:
            # Use select to check if stdin has data available without blocking
            rlist, _, _ = select.select([sys.stdin], [], [], 0.1)  # Non-blocking read

            if rlist:
                user_input = sys.stdin.readline().strip()
                if user_input.lower() == "exit":
                    print("Exiting program.")
                    return  # Exit cleanly
                try:
                    send_bluetooth_command(user_input)
                except RuntimeError as e:
                    print(f"Error sending command: {e}")
            time.sleep(0.1)  # Add a small delay to reduce CPU usage

    except KeyboardInterrupt:
        print("\nProgram interrupted. Exiting.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

